PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,employee_code TEXT NOT NULL UNIQUE,username_normalized TEXT NOT NULL UNIQUE,username TEXT NOT NULL,display_name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','employee')),active INTEGER NOT NULL DEFAULT 1,default_password_pending INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),authenticated_at TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS attendance_events(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),employee_code_snapshot TEXT NOT NULL,display_id TEXT,attempt_id TEXT UNIQUE,recorded_at TEXT NOT NULL,committed_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_user_time ON attendance_events(user_id,recorded_at,id);
CREATE INDEX IF NOT EXISTS events_time ON attendance_events(recorded_at,id);
CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),qr_interval INTEGER NOT NULL DEFAULT 5,schedule_version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS displays(id TEXT PRIMARY KEY,label TEXT NOT NULL,credential_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS qr_challenges(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,display_id TEXT NOT NULL REFERENCES displays(id),schedule_version INTEGER NOT NULL,interval_start INTEGER NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,UNIQUE(display_id,schedule_version,interval_start));
CREATE TABLE IF NOT EXISTS rate_limits(bucket TEXT PRIMARY KEY,window_started_at TEXT NOT NULL,request_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS browser_flows(token_hash TEXT PRIMARY KEY,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attendance_attempts(id TEXT PRIMARY KEY,challenge_id TEXT NOT NULL REFERENCES qr_challenges(id),browser_flow_hash TEXT NOT NULL,captured_at TEXT NOT NULL,expires_at TEXT NOT NULL,completed_user_id TEXT REFERENCES users(id),completed_event_id TEXT REFERENCES attendance_events(id));
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS flows_expiry ON browser_flows(expires_at);
CREATE INDEX IF NOT EXISTS challenges_expiry ON qr_challenges(expires_at);
CREATE INDEX IF NOT EXISTS attempts_expiry ON attendance_attempts(expires_at);
INSERT OR IGNORE INTO settings(id,qr_interval,schedule_version,updated_at) VALUES(1,5,1,CURRENT_TIMESTAMP);
